private static readonly Random _rng = new Random();

public async Task SetWithJitterAsync(string key, string value, TimeSpan baseTtl)
{
    var db = _redis.GetDatabase();
    var jitterPercent = _rng.NextDouble() * 0.2 - 0.1; // -10% to +10%
    var jitteredTtl = TimeSpan.FromTicks((long)(baseTtl.Ticks * (1 + jitterPercent)));

    await db.StringSetAsync(key, value, jitteredTtl);
}

import Redis from 'ioredis';
const redis = new Redis();

async function getWithMutex(key, ttlSeconds, rebuildFn) {
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  const lockKey = `${key}:lock`;
  const lockAcquired = await redis.set(lockKey, '1', 'NX', 'EX', 10);

  if (lockAcquired) {
    try {
      const fresh = await rebuildFn();
      await redis.setex(key, ttlSeconds, JSON.stringify(fresh));
      return fresh;
    } finally {
      await redis.del(lockKey);
    }
  } else {
    await new Promise(r => setTimeout(r, 50));
    return getWithMutex(key, ttlSeconds, rebuildFn);
  }
}
